import pandas as pd


def run(inputs: dict) -> dict:
    profile = inputs["customer_profile"]
    changes = inputs["profile_changes"]

    def _isna(v):
        return v is None or (isinstance(v, float) and pd.isna(v))

    # Build initial per-customer state map from customer_profile
    prof_map = {}
    for _, row in profile.iterrows():
        cid = int(row["customer_id"])
        prof_map[cid] = {
            "email": None if _isna(row["email"]) else row["email"],
            "phone": None if _isna(row["phone"]) else row["phone"],
            "tier": None if _isna(row["tier"]) else row["tier"],
            "updated_seq": int(row["updated_seq"]),
        }

    def resolve_field(raw, current, is_email=False):
        # NULL (missing) -> leave unchanged
        if _isna(raw):
            return current
        # sentinel -> explicitly set to NULL
        if isinstance(raw, str) and raw == "<<NULL>>":
            return None
        # normal value
        if is_email and isinstance(raw, str):
            return raw.strip().lower()
        return raw

    def eq_nullsafe(a, b):
        if _isna(a) and _isna(b):
            return True
        return a == b

    # Sort changes deterministically: by customer_id, then by change_seq
    # (change_seq is guaranteed unique, so no further tie-break is needed).
    changes_sorted = changes.sort_values(["customer_id", "change_seq"], kind="mergesort")

    grouped = changes_sorted.groupby("customer_id", sort=False)

    for cid, grp in grouped:
        cid = int(cid)
        existed = cid in prof_map

        if existed:
            state = prof_map[cid]
            watermark = state["updated_seq"]
            applicable = grp[grp["change_seq"] > watermark]
        else:
            state = {"email": None, "phone": None, "tier": None, "updated_seq": None}
            applicable = grp

        for _, ch in applicable.iterrows():
            new_email = resolve_field(ch["email"], state["email"], is_email=True)
            new_phone = resolve_field(ch["phone"], state["phone"], is_email=False)
            new_tier = resolve_field(ch["tier"], state["tier"], is_email=False)

            if not existed:
                # Creation: never a no-op, regardless of resulting values.
                state["email"] = new_email
                state["phone"] = new_phone
                state["tier"] = new_tier
                state["updated_seq"] = int(ch["change_seq"])
                existed = True
            else:
                if (
                    eq_nullsafe(new_email, state["email"])
                    and eq_nullsafe(new_phone, state["phone"])
                    and eq_nullsafe(new_tier, state["tier"])
                ):
                    # No-op change: values unchanged, watermark not advanced.
                    pass
                else:
                    state["email"] = new_email
                    state["phone"] = new_phone
                    state["tier"] = new_tier
                    state["updated_seq"] = int(ch["change_seq"])

        prof_map[cid] = state

    rows = []
    for cid, state in prof_map.items():
        rows.append(
            {
                "customer_id": cid,
                "email": state["email"],
                "phone": state["phone"],
                "tier": state["tier"],
                "updated_seq": state["updated_seq"],
            }
        )

    result = pd.DataFrame(
        rows, columns=["customer_id", "email", "phone", "tier", "updated_seq"]
    )
    if not result.empty:
        result["customer_id"] = result["customer_id"].astype("int64")
        result["updated_seq"] = result["updated_seq"].astype("int64")
    else:
        result["customer_id"] = result["customer_id"].astype("int64")
        result["updated_seq"] = result["updated_seq"].astype("int64")

    return {"new_profile": result}
